// test/parity/expected.json is generated by the JavaScript reference
// (plagx-preflight, npm run parity). Every case must match exactly.
import 'dart:convert';
import 'dart:io';

import 'package:plagx_preflight/plagx_preflight.dart';
import 'package:test/test.dart';

void main() {
  final data = jsonDecode(File('test/parity/expected.json').readAsStringSync()) as Map<String, dynamic>;
  final optionSets = data['optionSets'] as Map<String, dynamic>;
  const encoder = JsonEncoder.withIndent('  ');

  DraftResult run(String text, Map<String, dynamic> o) => checkDraft(
        text,
        minWords: o['minWords'] as int?,
        maxWords: o['maxWords'] as int?,
        style: (o['style'] as String?) ?? 'apa',
        checks: (o['checks'] as List?)?.cast<String>(),
        requiredHeadings: (o['requiredHeadings'] as List?)?.cast<String>() ?? const [],
      );

  for (final c in (data['cases'] as List).cast<Map<String, dynamic>>()) {
    test('${c['fixture']} / ${c['options']}', () {
      final text = utf8.decode(File('test/fixtures/${c['fixture']}').readAsBytesSync());
      final result = run(text, optionSets[c['options']] as Map<String, dynamic>);
      expect(encoder.convert(result.toJson()), encoder.convert(c['result']));
    });
  }

  test('covers every fixture', () {
    expect((data['cases'] as List).length, 160);
    expect(data['version'], version);
  });
}
